<template>
 <div class="ai-workspace" :class="embedded?'space-y-4':'ai-admin-shell'">
  <AiPageHeader v-if="!embedded" title="Nguồn RSS"><template #actions><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy||loading" @click="refresh">Tải lại</button><ActionButton v-if="active==='sources'" kind="create" @click="edit()">Thêm nguồn RSS</ActionButton></template><template #tabs><nav role="tablist" aria-label="Nguồn RSS" class="ai-tabs"><button v-for="(tab,index) in tabs" :id="'alert-tab-'+tab.key" :key="tab.key" type="button" role="tab" :aria-selected="active===tab.key" :aria-controls="'alert-panel-'+tab.key" :tabindex="active===tab.key?0:-1" @click="active=tab.key" @keydown="tabKey($event,index)">{{ tab.label }}</button></nav></template></AiPageHeader>
  <div :class="['space-y-4', {'ai-admin-body':!embedded}]">
  <p v-if="error" role="alert" class="p-3 rounded-xl bg-rose-50 text-rose-800">{{ error }}</p><p v-if="message" role="status" class="p-3 rounded-xl bg-blue-50 text-blue-900">{{ message }}</p>
  <p v-if="!configured&&!loading" role="status" class="p-3 rounded-xl border border-amber-200 bg-amber-50 text-amber-900">RSS vẫn nhận tiêu đề. AI sẽ đánh giá và đọc bài khi <a href="#ai-settings" class="underline font-semibold">cấu hình AI</a> sẵn sàng.</p>
  <section v-if="active==='sources'" id="alert-panel-sources" :role="embedded?undefined:'tabpanel'" :aria-labelledby="embedded?undefined:'alert-tab-sources'" class="ai-panel">
   <div class="ai-toolbar"><h3 class="ui-section-title">Nguồn thu thập</h3><div class="flex gap-3 items-center flex-wrap"><label class="flex items-center gap-2"><input v-model="showDeleted" type="checkbox" :disabled="busy"/>Nguồn đã xóa</label><ActionButton v-if="embedded" kind="create" @click="edit()">Thêm nguồn RSS</ActionButton></div></div>
   <LoadingSpinner v-if="loading" text="Đang tải nguồn RSS..." />
   <div v-else class="ai-records-layout"><div class="ai-wide-list ai-table-scroll"><table class="ai-table"><colgroup><col class="ai-stt-column"/><col style="width:25%"/><col style="width:16%"/><col style="width:18%"/><col style="width:21%"/><col style="width:20%"/></colgroup><thead><tr><th scope="col" class="ai-stt">STT</th><th>Nguồn</th><th>Lịch quét</th><th>Lần quét gần nhất</th><th class="text-center">Kết quả</th><th class="text-center">Thao tác</th></tr></thead><tbody><tr v-for="(feed,index) in feeds" :key="feed.id"><td class="ai-stt">{{ (sourcePage-1)*sourcePageSize+index+1 }}</td><td><strong>{{ feed.name }}</strong></td><td><span class="inline-flex rounded-full px-2 py-1 font-semibold" :class="feed.enabled?'bg-blue-50 text-blue-800':'bg-slate-100 text-slate-700'">{{ feed.enabled?feed.scanTime:'Tắt lịch' }}</span><p v-if="feed.enabled&&feed.nextScanAt" class="mt-1 text-slate-600">{{ date(feed.nextScanAt) }}</p></td><td>{{ feed.lastScan?date(feed.lastScan.queuedAt):'Chưa quét' }}</td><td class="text-center"><span class="ai-badge" :class="scanBadge(feed.lastScan?.status)">{{ scanLabel(feed.lastScan?.status) }}</span><p v-if="feed.lastScan?.status==='Completed'" class="mt-1 text-slate-600">{{ formatNumber(feed.lastScan.added) }} mới · {{ formatNumber(feed.lastScan.duplicates) }} trùng<span v-if="feed.lastScan.blocked"> · {{ formatNumber(feed.lastScan.blocked) }} bỏ qua</span></p><p v-if="feed.lastScan?.error" class="text-rose-800 mt-1">{{ feed.lastScan.error }}</p></td><td class="text-center"><div class="flex justify-center gap-2"><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-secondary whitespace-nowrap" :disabled="busy||running(feed)" @click="scan(feed)">{{ running(feed)?'Đang quét':'Quét ngay' }}</button><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-secondary" :disabled="busy||running(feed)" @click="edit(feed)">Sửa</button><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-danger" :disabled="busy||running(feed)" @click="deleteFeed(feed)">Xóa</button><button v-else type="button" class="ui-btn ui-btn-secondary" :disabled="busy" @click="restoreFeed(feed)">Khôi phục</button></div></td></tr></tbody></table></div><div class="ai-compact-list"><article v-for="(feed,index) in feeds" :key="feed.id" class="ai-record"><p class="ai-muted mb-2">STT {{ (sourcePage-1)*sourcePageSize+index+1 }}</p><div class="flex flex-wrap justify-between gap-3 items-start"><h3 class="ai-record-title">{{ feed.name }}</h3><span class="ai-badge" :class="scanBadge(feed.lastScan?.status)">{{ scanLabel(feed.lastScan?.status) }}</span></div><dl class="ai-record-meta"><div><dt>Lịch quét</dt><dd>{{ feed.enabled?feed.scanTime+' hằng ngày':'Tắt lịch' }}</dd></div><div><dt>Lần quét gần nhất</dt><dd>{{ feed.lastScan?date(feed.lastScan.queuedAt):'Chưa quét' }}</dd></div></dl><p v-if="feed.enabled&&feed.nextScanAt" class="ai-muted mt-3">Lần tới: {{ date(feed.nextScanAt) }}</p><p v-if="feed.lastScan?.status==='Completed'" class="mt-3">{{ formatNumber(feed.lastScan.added) }} mới · {{ formatNumber(feed.lastScan.duplicates) }} trùng · {{ formatNumber(feed.lastScan.blocked) }} bỏ qua</p><p v-if="feed.lastScan?.error" class="text-rose-800 mt-3">{{ feed.lastScan.error }}</p><div class="ai-record-actions"><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-secondary" :disabled="busy||running(feed)" @click="edit(feed)">Sửa</button><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-danger" :disabled="busy||running(feed)" @click="deleteFeed(feed)">Xóa</button><button v-else type="button" class="ui-btn ui-btn-secondary" :disabled="busy" @click="restoreFeed(feed)">Khôi phục</button><button v-if="!showDeleted" type="button" class="ui-btn ui-btn-secondary" :disabled="busy||running(feed)" @click="scan(feed)">{{ running(feed)?'Đang quét':'Quét ngay' }}</button></div></article></div><div v-if="!feeds.length" class="ai-empty"><p class="font-semibold">Chưa có nguồn RSS</p><p class="text-slate-600">Thêm URL RSS từ Google Alerts để nhận tiêu đề mới.</p><ActionButton kind="create" @click="edit()">Thêm nguồn RSS</ActionButton></div></div>
   <AiListPagination v-model:page="sourcePage" v-model:page-size="sourcePageSize" :total="sourceTotal" :disabled="loading||busy" item-label="nguồn RSS" fixed/>
  </section>
  <section v-else-if="active==='titles'" id="alert-panel-titles" role="tabpanel" aria-labelledby="alert-tab-titles"><AiInboxPanel mode="alerts" :metrics="metrics" :configured="configured" @view-suggestions="navigateReview" /></section>
  <section v-else id="alert-panel-history" :role="embedded?undefined:'tabpanel'" :aria-labelledby="embedded?undefined:'alert-tab-history'" class="ai-panel"><LoadingSpinner v-if="historyLoading" text="Đang tải lịch sử quét..."/><div v-else class="ai-records-layout"><div class="ai-wide-list ai-table-scroll"><table class="ai-table"><colgroup><col class="ai-stt-column"/><col style="width:30%"/><col style="width:22%"/><col style="width:16%"/><col style="width:32%"/></colgroup><thead><tr><th scope="col" class="ai-stt">STT</th><th>Nguồn / Thời gian</th><th>Chạy bởi</th><th class="text-center">Trạng thái</th><th class="text-center">Kết quả quét</th></tr></thead><tbody><tr v-for="(run,index) in history" :key="run.id"><td class="ai-stt">{{ (historyPage-1)*historyPageSize+index+1 }}</td><td><p class="font-semibold">{{ run.feedName }}</p><p class="ai-muted mt-1">{{ date(run.queuedAt) }}</p></td><td>{{ run.trigger==='Scheduled'?'Lịch tự động':run.requestedBy }}</td><td class="text-center"><span class="ai-badge" :class="scanBadge(run.status)">{{ scanLabel(run.status) }}</span></td><td class="text-center"><p>{{ formatNumber(run.received) }} nhận · {{ formatNumber(run.added) }} mới</p><p class="ai-muted mt-1">{{ formatNumber(run.duplicates) }} trùng · {{ formatNumber(run.blocked) }} bỏ qua</p><p v-if="run.error" class="text-rose-800 mt-2">{{ run.error }}</p></td></tr></tbody></table></div><div class="ai-compact-list"><article v-for="(run,index) in history" :key="run.id" class="ai-record"><p class="ai-muted mb-2">STT {{ (historyPage-1)*historyPageSize+index+1 }}</p><div class="flex flex-wrap justify-between gap-3"><h3 class="ai-record-title">{{ run.feedName }}</h3><span class="ai-badge" :class="scanBadge(run.status)">{{ scanLabel(run.status) }}</span></div><p class="ai-muted mt-2">{{ date(run.queuedAt) }} · {{ run.trigger==='Scheduled'?'Lịch tự động':run.requestedBy }}</p><dl class="ai-record-meta"><div><dt>Đã nhận / Mới</dt><dd>{{ formatNumber(run.received) }} / {{ formatNumber(run.added) }}</dd></div><div><dt>Trùng / Bỏ qua</dt><dd>{{ formatNumber(run.duplicates) }} / {{ formatNumber(run.blocked) }}</dd></div></dl><p v-if="run.error" class="text-rose-800 mt-3">{{ run.error }}</p></article></div><div v-if="!history.length" class="ai-empty"><strong>Chưa có lượt quét.</strong></div></div><AiListPagination v-model:page="historyPage" v-model:page-size="historyPageSize" :total="historyTotal" :disabled="historyLoading||busy" item-label="lượt quét" fixed/></section>
   <details v-if="active==='sources'" class="ai-panel p-4 text-slate-600"><summary class="cursor-pointer font-semibold">Thiết lập nguồn và phạm vi đọc</summary><div class="mt-3 space-y-3"><p>Tạo cảnh báo tại <a href="https://www.google.com/alerts" target="_blank" rel="noopener noreferrer" class="underline text-blue-700">Google Alerts</a> (chọn Nguồn: <em>Tự động</em> hoặc <em>Trang web</em>, Phân phối: <em>Nguồn cấp dữ liệu RSS</em>) rồi sao chép URL RSS vào đây. Lần quét đầu nhận các bài hiện có trong RSS; những lần sau bỏ qua bài trùng URL.</p><p>Quét mỗi ngày nhận tiêu đề → AI đánh giá theo Thiết lập từ khóa của văn bản → đọc bài và đề xuất cho các mục tiêu liên quan. Tiêu đề chưa rõ chờ admin chọn chỉ số. Bài ngoài tên miền cho phép bị bỏ qua trước khi gửi AI.</p><p>Backend phải hoạt động vào giờ quét; khi khởi động lại sẽ quét bù một lượt nếu đã quá giờ. Giới hạn 200 tiêu đề mỗi nguồn/lượt; không duyệt hoặc ghi báo cáo tự động.</p><p class="break-words">Nguồn bài cho phép: {{ allowedHosts.join(', ') }}</p></div></details>
   </div>
   <div v-if="editing" v-accessible-dialog="closeEdit" class="fixed inset-0 z-50 bg-slate-900/60 flex items-center justify-center p-3" @click.self="closeEdit"><form class="bg-white rounded-2xl w-full max-w-xl max-h-[90dvh] flex flex-col shadow-xl overflow-hidden" @submit.prevent="save"><header class="p-4 sm:p-6 border-b border-slate-200 flex justify-between items-center gap-3"><h3 class="ui-title">{{ form.id?'Sửa nguồn RSS':'Thêm nguồn RSS' }}</h3><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy" @click="closeEdit">Đóng</button></header><div class="p-4 sm:p-6 overflow-y-auto min-h-0 space-y-4"><p v-if="formError" role="alert" class="p-3 rounded-xl bg-rose-50 text-rose-800">{{ formError }}</p><div><label for="alert-name" class="font-semibold text-sm text-slate-800">Tên nguồn theo dõi</label><input id="alert-name" v-model.trim="form.name" required minlength="3" maxlength="150" class="field mt-1" placeholder="Ví dụ: Google Alerts - Chuyển đổi số Tuyên Quang" /></div><div><div class="flex justify-between items-center"><label for="alert-url" class="font-semibold text-sm text-slate-800">URL RSS từ Google Alerts</label><a href="https://www.google.com/alerts" target="_blank" rel="noopener noreferrer" class="text-xs text-blue-600 hover:underline inline-flex items-center gap-1 font-medium">Tạo cảnh báo trên Google Alerts ↗</a></div><input id="alert-url" v-model.trim="form.feedUrl" type="url" required maxlength="1000" class="field mt-1" placeholder="https://www.google.com/alerts/feeds/..." /><p class="text-xs text-slate-500 mt-1">Dán liên kết RSS lấy từ Google Alerts (kết quả bao quát cả Cổng TTĐT và Web).</p></div><label class="flex gap-3 items-center text-sm font-medium cursor-pointer"><input v-model="form.enabled" type="checkbox" class="accent-blue-600 rounded" />Bật lịch quét hằng ngày</label><div><label for="alert-time" class="font-semibold text-sm text-slate-800">Giờ quét (Việt Nam)</label><input id="alert-time" v-model="form.scanTime" type="time" required class="field max-w-48 mt-1" :disabled="!form.enabled" /></div></div><footer class="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-2"><button type="button" class="ui-btn ui-btn-secondary" :disabled="busy" @click="closeEdit">Hủy</button><button type="submit" class="ui-btn ui-btn-primary" :disabled="busy">{{ busy?'Đang lưu…':'Lưu nguồn' }}</button></footer></form></div>
 </div>
</template>
<script setup>
import {activeDocumentId,withActiveDocument} from '../services/documentContext';
import AiListPagination from '../components/AiListPagination.vue';

import {confirmModal} from '../services/confirm';
import AiPageHeader from '../components/AiPageHeader.vue';
import {getStatusBadgeClass} from '../shared/statusPresentation';
import {ref,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {fetchWithAuth} from '../services/auth';
import {getApiUrl} from '../config/api';
import {formatDateTime,formatNumber} from '../shared/formatters';
import ActionButton from '../components/ActionButton.vue';
import LoadingSpinner from '../components/LoadingSpinner.vue';
import AiInboxPanel from '../components/AiInboxPanel.vue';
const emit=defineEmits(['navigate']);
const props=defineProps({embedded:Boolean,initialTab:{type:String,default:'sources'}});
defineExpose({refresh});
const showDeleted=ref(false);
const feeds=ref([]),metrics=ref([]),configured=ref(false),allowedHosts=ref([]),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),active=ref(props.initialTab);
const tabs=[{key:'sources',label:'Nguồn RSS'},{key:'titles',label:'Tiêu đề đã nhận'},{key:'history',label:'Lịch sử quét'}];
const sourcePage=ref(1),sourcePageSize=ref(5),sourceTotal=ref(0);
const historyPageSize=ref(5);
const history=ref([]),historyTotal=ref(0),historyPage=ref(1),historyLoading=ref(false),editing=ref(false),formError=ref(''),form=ref({});let version=0,historyVersion=0,timer;
const date=value=>value?formatDateTime(value):'—';
const running=feed=>['Queued','Running'].includes(feed.lastScan?.status);
const scanBadge=status=>getStatusBadgeClass(status==='Completed'?'Approved':status==='Error'?'Rejected':['Queued','Running'].includes(status)?'InProgressOnTime':'NotStarted');
const scanLabel=status=>({Queued:'Chờ quét',Running:'Đang quét',Completed:'Hoàn tất',Error:'Lỗi quét'}[status]||'—');
async function api(path='',options){const response=await fetchWithAuth(getApiUrl(withActiveDocument('/api/ai-alerts'+path)),options);if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message||`Không xử lý được yêu cầu (HTTP ${response.status}).`);}return response.json();}
async function load(initial=false){const request=++version;if(initial)loading.value=true;try{const data=await api('?page='+sourcePage.value+(showDeleted.value?'&deleted=true':''));if(request!==version)return;feeds.value=data.feeds;sourceTotal.value=data.total;sourcePage.value=data.page;configured.value=data.configured;allowedHosts.value=data.allowedHosts;}catch(e){if(request===version)error.value=e.message;}finally{if(request===version)loading.value=false;}}
async function loadHistory(){const request=++historyVersion;historyLoading.value=!history.value.length;try{const data=await api('/scans?page='+historyPage.value);if(request!==historyVersion)return;history.value=data.items;historyTotal.value=data.total;historyPage.value=data.page;}catch(e){if(request===historyVersion)error.value=e.message;}finally{if(request===historyVersion)historyLoading.value=false;}}
function refresh(){error.value='';load();if(active.value==='history')loadHistory();}
function edit(feed){
  form.value=feed?{id:feed.id,name:feed.name,feedUrl:feed.feedUrl,enabled:feed.enabled,scanTime:feed.scanTime}:{name:'',feedUrl:'',enabled:false,scanTime:'08:00'};
  formError.value='';
  editing.value=true;
}
function closeEdit(){if(!busy.value)editing.value=false;}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{const isNew=!form.value.id;const response=await api(form.value.id?'/'+form.value.id:'',{method:form.value.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form.value,documentId:activeDocumentId.value})});message.value=response.message;editing.value=false;if(isNew&&sourcePage.value!==1)sourcePage.value=1;else await load();}catch(e){formError.value=e.message;}finally{busy.value=false;}}
async function scan(feed){if(busy.value||running(feed))return;busy.value=true;error.value='';try{await api('/'+feed.id+'/scan',{method:'POST'});message.value='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function deleteFeed(feed){
 if(busy.value||running(feed))return;
 if(!await confirmModal({title:'Xóa nguồn RSS',message:`Xóa nguồn “${feed.name}”? Nguồn sẽ dừng thu thập; bài viết, dẫn chứng và lịch sử vẫn được giữ. Có thể khôi phục trong Nguồn đã xóa.`,confirmText:'Xóa nguồn',type:'danger'}))return;
 await changeDeleted(feed,false);
}
async function restoreFeed(feed){await changeDeleted(feed,true);}
async function changeDeleted(feed,restore){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await api('/'+feed.id+(restore?'/restore':''),{method:restore?'POST':'DELETE'});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
watch(showDeleted,()=>{error.value='';if(sourcePage.value!==1)sourcePage.value=1;else load();});
watch(sourcePage,()=>load());
function navigateReview(){emit('navigate','ai-review');}
function tabKey(event,index){let target;if(event.key==='ArrowRight')target=(index+1)%tabs.length;else if(event.key==='ArrowLeft')target=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')target=0;else if(event.key==='End')target=tabs.length-1;else return;event.preventDefault();active.value=tabs[target].key;nextTick(()=>document.getElementById('alert-tab-'+tabs[target].key)?.focus());}
watch(()=>props.initialTab,value=>active.value=value);
watch(active,value=>{if(value==='history')loadHistory();});watch(historyPage,loadHistory);
watch(activeDocumentId,()=>{version++;historyVersion++;editing.value=false;feeds.value=[];history.value=[];sourcePage.value=1;historyPage.value=1;load();loadHistory();});
onMounted(async()=>{load(true);if(active.value==='history')loadHistory();try{const res=await fetchWithAuth(getApiUrl(withActiveDocument('/api/ai-data/catalog')));if(res.ok)metrics.value=(await res.json()).internetMetrics;}catch{}timer=setInterval(()=>{if(!busy.value&&!editing.value&&document.visibilityState==='visible'){load();if(active.value==='history')loadHistory();}},15000);});onUnmounted(()=>{version++;historyVersion++;clearInterval(timer);});
</script>
<style scoped>
.field{display:block;width:100%;height:var(--ui-control-height);margin-top:8px;border:1px solid var(--color-slate-300);border-radius:8px;padding:8px 12px;background:white}
</style>
